AND (
      (n.scope_type <> 'USER' AND EXISTS (
            SELECT 1 FROM sys_user u
             WHERE u.user_id = #{userId}
               AND u.del_flag = '0'
               AND (n.scope_type = 'ALL'
                    OR (n.scope_type = 'DEPT'     AND u.dept_id     = n.scope_id)
                    OR (n.scope_type = 'POSITION' AND (
                           (n.scope_id <> 0 AND u.position_id = n.scope_id)
                        OR (n.scope_id = 0 AND )
                    )))
      ))
