INSERT INTO notice_read (notice_id, user_id, read_time) SELECT n.id, #{userId}, NOW() FROM notice n WHERE AND (n.publisher_id IS NULL OR n.publisher_id <> #{userId})
AND n.msg_type = #{msgType}
ON DUPLICATE KEY UPDATE read_time = read_time
